-- Paket 14.11.2026 (3): compact header on phones (new chunk HtsHeaderCompact, call appended to chunk Footers). Text is hex-encoded on purpose.
SET NAMES utf8mb4;
SET SESSION group_concat_max_len = 100000;
-- APPLY. Saves chunk Footers to hts_bak_20261114_hd first; safe to run twice.
CREATE TABLE IF NOT EXISTS hts_bak_20261114_hd (kind VARCHAR(16) NOT NULL, el_id INT NOT NULL, body MEDIUMTEXT, saved_at DATETIME NOT NULL, PRIMARY KEY (kind, el_id)) DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO hts_bak_20261114_hd (kind, el_id, body, saved_at) SELECT 'chunk', c.id, c.snippet, NOW() FROM modx_site_htmlsnippets c WHERE c.name = 'Footers' AND c.snippet NOT LIKE '%[[$HtsHeaderCompact]]%';
UPDATE modx_site_htmlsnippets c SET c.snippet = CONCAT(CONVERT(c.snippet USING utf8mb4), _utf8mb4 0x0A5B5B24487473486561646572436F6D706163745D5D) WHERE c.name = 'Footers' AND c.snippet NOT LIKE '%[[$HtsHeaderCompact]]%' AND (SELECT COUNT(*) FROM (SELECT id FROM modx_site_htmlsnippets WHERE name = 'Footers') z) = 1;
INSERT INTO modx_site_htmlsnippets (source, name, description, category, snippet, properties, static, static_file)
SELECT 1, 'HtsHeaderCompact', _utf8mb4 0xD09AD0BED0BCD0BFD0B0D0BAD182D0BDD0B0D18F20D188D0B0D0BFD0BAD0B020D0BDD0B020D182D0B5D0BBD0B5D184D0BED0BDD0B52028D182D0BED0BBD18CD0BAD0BE20D0BED184D0BED180D0BCD0BBD0B5D0BDD0B8D0B529, 0, _utf8mb4 , 'a:0:{}', 0, '' FROM (SELECT 1 AS x) d
WHERE NOT EXISTS (SELECT 1 FROM modx_site_htmlsnippets WHERE name = 'HtsHeaderCompact');
SELECT itog, COUNT(*) AS n, GROUP_CONCAT(chto ORDER BY chto SEPARATOR '; ') AS what FROM (
SELECT _utf8mb4 0x312E20D09ED0B1D189D0B8D0B920D0BFD0BED0B4D0B2D0B0D0BB20D181D0B0D0B9D182D0B02028D187D0B0D0BDD0BA20466F6F7465727329 AS chto, CASE WHEN (SELECT COUNT(*) FROM modx_site_htmlsnippets WHERE name = 'Footers') <> 1 THEN _utf8mb4 0xD09DD09520D0A1D09ED092D09FD090D094D090D095D0A220E2809420D181D182D0BED0BF2C20D181D0BAD180D0B8D0BDD188D0BED182 WHEN (SELECT snippet FROM modx_site_htmlsnippets WHERE name = 'Footers') LIKE '%[[$HtsHeaderCompact]]%' THEN _utf8mb4 0xD0A3D096D09520D09FD095D0A0D095D09DD095D0A1D095D09DD09E ELSE _utf8mb4 0xD0A1D09ED092D09FD090D094D090D095D0A220E2809420D0BCD0BED0B6D0BDD0BE20D0BFD0B5D180D0B5D0BDD0BED181D0B8D182D18C END AS itog
UNION ALL
SELECT _utf8mb4 0x322E20D09DD0BED0B2D18BD0B920D187D0B0D0BDD0BA20487473486561646572436F6D70616374, CASE WHEN (SELECT COUNT(*) FROM modx_site_htmlsnippets WHERE name = 'HtsHeaderCompact') = 0 THEN _utf8mb4 0xD0A1D09ED092D09FD090D094D090D095D0A220E2809420D0BCD0BED0B6D0BDD0BE20D0BFD0B5D180D0B5D0BDD0BED181D0B8D182D18C ELSE _utf8mb4 0xD0A3D096D09520D09FD095D0A0D095D09DD095D0A1D095D09DD09E END
) q GROUP BY itog;
